import { execSync } from 'child_process'

let failed = false

function run(cmd: string) {
  try {
    const result = execSync(cmd, { stdio: 'pipe' }).toString()
    // Filter out lines that start with // or /*
    return result.split('\n')
      .filter((line: string) => !line.trim().startsWith('//') && !line.includes('/*'))
      .join('\n')
  } catch (e: any) {
    if (e.stdout) {
      const result = e.stdout.toString()
      // Filter out lines that start with // or /*
      return result.split('\n')
        .filter((line: string) => !line.trim().startsWith('//') && !line.includes('/*'))
        .join('\n')
    }

    const stderr = e.stderr ? e.stderr.toString() : ''
    if (e.status === 1 && stderr.trim().length === 0) {
      return ''
    }

    failed = true
    return `COMMAND_ERROR: ${cmd}\n${stderr || e.message || 'Unknown command error'}`
  }
}

function check(name: string, result: string) {
  if (result.trim().length > 0) {
    console.error(`❌ ${name} VIOLATION`)
    console.error(result)
    failed = true
