      console.log(`❌ Memory Leaks: ${this.results.memoryLeaks ? 'PASS' : 'FAIL'}`);
      console.log(`⏱️  Duração: ${duration}ms`);
      console.log(`🚨 Erro: ${error instanceof Error ? error.message : String(error)}`);
      console.log('==========================================\n');

      throw error;
    }
