/**
 * Garante o banco correto sem duplicar: prioriza vendas_app > grs.
 * Conecta ao MySQL sem database, lista bancos, escolhe ou cria o adequado e atualiza .env.
 *
 * Lógica:
 * 1. Se vendas_app existir → usar (nunca criar)
 * 2. Se grs existir → usar (nunca criar)
 * 3. Se nenhum existir → criar grs
 * 4. Atualiza .env com DB_NAME=banco escolhido
 *
 * Requer: DB_HOST, DB_USER, DB_PASSWORD (e opcionalmente DB_PORT) no .env. DB_NAME é opcional (será definido).
 */
import "dotenv/config";
import mysql from "mysql2/promise";
import * as fs from "node:fs";
import * as path from "node:path";

function getConnectionConfig(): { host: string; port: number; user: string; password: string } {
  if (process.env.DATABASE_URL?.trim()) {
    try {
      const url = new URL(process.env.DATABASE_URL);
      if (!url.hostname || !url.username || url.password === undefined) {
        throw new Error("DATABASE_URL incompleta.");
      }
      return {
        host: url.hostname,
        port: parseInt(url.port || "3306", 10),
        user: url.username,
        password: url.password,
      };
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      throw new Error(`DATABASE_URL inválida: ${msg}. Defina DATABASE_URL ou DB_HOST, DB_USER, DB_PASSWORD.`);
    }
  }
  const host = process.env.DB_HOST?.trim();
  const user = process.env.DB_USER?.trim();
  const password = process.env.DB_PASSWORD;
  if (!host || !user || password === undefined) {
    throw new Error(
      "Credenciais obrigatórias. Defina DATABASE_URL ou DB_HOST, DB_USER, DB_PASSWORD (DB_NAME será definido automaticamente)."
    );
  }
  return {
    host,
    port: parseInt(process.env.DB_PORT ?? "3306", 10),
    user,
    password,
  };
}

function getEnvPath(): string {
  const root = process.cwd();
  return path.join(root, ".env");
}

function updateEnvDbName(chosenDb: string): boolean {
  const envPath = getEnvPath();
  if (!fs.existsSync(envPath)) return false;
  const content = fs.readFileSync(envPath, "utf-8");
  const lines = content.split(/\r?\n/);
  const newLine = `DB_NAME=${chosenDb}`;
  let found = false;
  const out = lines.map((line) => {
    if (/^\s*DB_NAME\s*=/.test(line)) {
      found = true;
      return newLine;
    }
    return line;
  });
  if (!found) out.push(newLine);
  fs.writeFileSync(envPath, out.join("\n"), "utf-8");
  return true;
}

async function main(): Promise<any> {
  const config = getConnectionConfig();
  const connection = await mysql.createConnection(config);
  let chosenDb: string;

  try {
    const [rows] = await connection.query("SHOW DATABASES");
    const raw = (rows as { Database?: string }[] | undefined) ?? [];
    const databases = raw.map((r) => (r && "Database" in r ? String(r.Database) : "")).filter(Boolean);

    const vendasAppExists = databases.includes("vendas_app");
    const grsExists = databases.includes("grs");

    if (vendasAppExists) {
      chosenDb = "vendas_app";
      console.log("[ensure-database] Banco existente 'vendas_app' detectado. Será usado (não será criado duplicado).");
    } else if (grsExists) {
      chosenDb = "grs";
      console.log("[ensure-database] Banco existente 'grs' detectado. Será usado (não será criado duplicado).");
    } else {
      chosenDb = "grs";
      await connection.query("CREATE DATABASE IF NOT EXISTS `grs`");
      console.log("[ensure-database] Nenhum banco vendas_app/grs encontrado. Banco 'grs' criado.");
    }
  } finally {
    await connection.end();
  }

  const envPath = getEnvPath();
  if (fs.existsSync(envPath)) {
    const updated = updateEnvDbName(chosenDb);
    if (updated) {
      console.log("[ensure-database] .env atualizado: DB_NAME=" + chosenDb);
    }
  }

  process.env.DB_NAME = chosenDb;
  console.log("[ensure-database] Banco a ser usado:", chosenDb);
}

main().catch((err) => {
  console.error("[ensure-database] Erro:", err.message ?? err);
  process.exit(1);
});

/**
 * Script de correção massiva de tipos TypeScript
 * Corrige os erros mais comuns de forma automatizada
 */

import * as fs from 'fs';
import * as path from 'path';

// Padrões de correção massiva
const CORRECTIONS = [
  // Corrigir parâmetros implícitos em funções
  {
    pattern: /\((\w+)(?::\s*[^)]+)?\)\s*=>/g,
    replacement: '($1: any) =>',
    description: 'Adicionar tipo any a parâmetros implícitos'
  },
  
  // Corrigir parâmetros em reduce
  {
    pattern: /\.reduce\(\((\w+),\s*(\w+)\)\s*=>/g,
    replacement: '.reduce(($1: any, $2: any) =>',
    description: 'Tipar parâmetros reduce'
  },
  
  // Corrigir parâmetros em map
  {
    pattern: /\.map\((\w+)\s*=>/g,
    replacement: '.map(($1: any) =>',
    description: 'Tipar parâmetros map'
  },
  
  // Corrigir parâmetros em filter
  {
    pattern: /\.filter\((\w+)\s*=>/g,
    replacement: '.filter(($1: any) =>',
    description: 'Tipar parâmetros filter'
  },
  
  // Corrigir funções async sem retorno
  {
    pattern: /async\s+function\s+(\w+)\s*\([^)]*\)\s*\{/g,
    replacement: 'async function $1($&): Promise<any> {',
    description: 'Adicionar retorno Promise<any> a funções async'
  },
  
  // Corrigir array destructuring com fallback
  {
    pattern: /const\s+\[(\w+),\s*(\w+)\]\s*=\s*(\w+)\[0\];/g,
    replacement: 'const [$1, $2] = $3[0] ?? ["", 0];',
    description: 'Adicionar fallback para destructuring'
  }
];

function fixFile(filePath: string): void {
  try {
    let content = fs.readFileSync(filePath, 'utf-8');
    let modified = false;
    
    for (const correction of CORRECTIONS) {
      const originalContent = content;
      content = content.replace(correction.pattern, correction.replacement);
      
      if (content !== originalContent) {
        modified = true;
        console.log(`✅ ${correction.description} em ${path.basename(filePath)}`);
      }
    }
    
    if (modified) {
      fs.writeFileSync(filePath, content, 'utf-8');
      console.log(`📝 Arquivo corrigido: ${filePath}`);
    }
  } catch (error) {
    console.error(`❌ Erro ao corrigir ${filePath}:`, error);
  }
}

function findTsFiles(dir: string): string[] {
  const files: string[] = [];
  
  function scan(currentDir: string): void {
    const items = fs.readdirSync(currentDir);
    
    for (const item of items) {
      const fullPath = path.join(currentDir, item);
      const stat = fs.statSync(fullPath);
      
      if (stat.isDirectory() && !item.includes('node_modules')) {
        scan(fullPath);
      } else if (item.endsWith('.ts')) {
        files.push(fullPath);
      }
    }
  }
  
  scan(dir);
  return files;
}

// Executar correção massiva
const serverDir = path.join(__dirname, '..');
const tsFiles = findTsFiles(serverDir);

console.log(`🚀 Iniciando correção massiva de ${tsFiles.length} arquivos TypeScript...`);

let fixedCount = 0;
for (const file of tsFiles) {
  if (file.includes('server')) {
    fixFile(file);
    fixedCount++;
  }
}

console.log(`✨ Correção concluída! ${fixedCount} arquivos processados.`);
