import "dotenv/config";
import mysql from "mysql2/promise";

function getConnectionConfig(): { host: string; port: number; user: string; password: string; database: string } {
  const host = process.env.DB_HOST?.trim();
  const user = process.env.DB_USER?.trim();
  const password = process.env.DB_PASSWORD || "";
  const database = process.env.DB_NAME?.trim() || "vendas_app";
  
  if (!host || !user || password === undefined) {
    throw new Error("Credenciais obrigatórias. Defina DB_HOST, DB_USER, DB_PASSWORD.");
  }
  
  return {
    host,
    port: parseInt(process.env.DB_PORT ?? "3306", 10),
    user,
    password,
    database,
  };
}

async function main(): Promise<void> {
  const config = getConnectionConfig();
  const connection = await mysql.createConnection(config);

  try {
    console.log("[seed-tenant] Criando tenant padrão...");
    
    // Inserir tenant padrão
    const [tenantResult] = await connection.execute(
      `INSERT INTO tenants (nome_empresa, plano, status, createdAt) VALUES (?, ?, ?, NOW())`,
      ["Empresa Padrão", "PROFESSIONAL", "ACTIVE"]
    );
    
    const tenantId = (tenantResult as any).insertId;
    console.log(`[seed-tenant] Tenant criado com ID: ${tenantId}`);
    
    // Inserir usuário admin
    const [userResult] = await connection.execute(
      `INSERT INTO users (tenantId, openId, name, email, role, createdAt, updatedAt, lastSignedIn) VALUES (?, ?, ?, ?, ?, NOW(), NOW(), NOW())`,
      [tenantId, "admin-local", "Administrador", "admin@local.com", "admin"]
    );
    
    const userId = (userResult as any).insertId;
    console.log(`[seed-tenant] Usuário admin criado com ID: ${userId}`);
    
    // Inserir vendedor admin
    const [vendedorResult] = await connection.execute(
      `INSERT INTO vendedores (tenantId, userId, nome, admin, ativo, createdAt, updatedAt) VALUES (?, ?, ?, ?, ?, NOW(), NOW())`,
      [tenantId, userId, "Administrador", 1, 1]
    );
    
    console.log(`[seed-tenant] Vendedor admin criado com ID: ${(vendedorResult as any).insertId}`);
    console.log("[seed-tenant] ✅ Dados iniciais criados com sucesso!");
    
  } finally {
    await connection.end();
  }
}

main().catch((err) => {
  console.error("[seed-tenant] Erro:", err.message ?? err);
  process.exit(1);
});

/**
 * Script para simular falha do banco e testar recuperação
 * Para: MySQL/MariaDB
 */
import "dotenv/config";
import * as mysql from "mysql2/promise";

async function simulateFailureAndRecovery() {
  console.log("🔥 Simulando falha do banco e recuperação...");
  
  // Configuração sem especificar o banco para forçar erro
  const configWithoutDb: mysql.PoolOptions = {
    host: process.env.DB_HOST || 'localhost',
    port: parseInt(process.env.DB_PORT || '3306', 10),
    user: process.env.DB_USER || 'root',
    password: process.env.DB_PASSWORD || '',
    waitForConnections: true,
    connectionLimit: 10,
    queueLimit: 0,
    enableKeepAlive: true,
    keepAliveInitialDelay: 30000,
    connectTimeout: 3000,
    maxIdle: 10,
    idleTimeout: 60000,
  };

  // Configuração correta
  const configWithDb: mysql.PoolOptions = {
    ...configWithoutDb,
    database: process.env.DB_NAME || 'vendas_app',
  };

  console.log("\n1. Testando configuração correta...");
  try {
    const pool = mysql.createPool(configWithDb);
    const conn = await pool.getConnection();
    await conn.ping();
    conn.release();
    await pool.end();
    console.log("✅ Configuração correta OK");
  } catch (error) {
    console.log("❌ Erro na configuração correta:", error instanceof Error ? error.message : error);
  }

  console.log("\n2. Simulando falha (banco inexistente)...");
  try {
    const pool = mysql.createPool({
      ...configWithDb,
      database: 'database_inexistente_que_nao_existe'
    });
    const conn = await pool.getConnection();
    await conn.ping();
    conn.release();
    await pool.end();
    console.log("❌ Não deveria conectar!");
  } catch (error) {
    console.log("✅ Falha simulada com sucesso:", error instanceof Error ? error.message : error);
  }

  console.log("\n3. Testando reconexão com banco correto...");
  try {
    const pool = mysql.createPool(configWithDb);
    const conn = await pool.getConnection();
    await conn.ping();
    conn.release();
    await pool.end();
    console.log("✅ Reconexão bem-sucedida!");
  } catch (error) {
    console.log("❌ Falha na reconexão:", error instanceof Error ? error.message : error);
  }

  console.log("\n🔥 Teste de falha e recuperação concluído!");
}

simulateFailureAndRecovery().catch(console.error);

