/**
 * Valida que a tabela idempotency_keys existe com UNIQUE(commandName, key).
 * Uso: tsx server/scripts/validate-idempotency-table.ts
 */
import "../_core/loadEnv.js";
import * as db from "../db/index.js";

async function main() {
  const conn = await db.getDb();
  if (!conn) {
    console.error("Banco indisponível.");
    process.exit(1);
  }
  const { sql } = db;
  try {
    const [rows]: any = await (conn as any).execute(sql`
      SELECT TABLE_NAME, COLUMN_NAME, COLUMN_DEFAULT, COLUMN_TYPE
      FROM INFORMATION_SCHEMA.COLUMNS
      WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'idempotency_keys'
      ORDER BY ORDINAL_POSITION
    `);
    const [idx]: any = await (conn as any).execute(sql`
      SELECT INDEX_NAME, COLUMN_NAME, NON_UNIQUE
      FROM INFORMATION_SCHEMA.STATISTICS
      WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'idempotency_keys'
      ORDER BY INDEX_NAME, SEQ_IN_INDEX
    `);
    console.log("--- Colunas idempotency_keys ---");
    if (!rows || rows.length === 0) {
      console.error("Tabela idempotency_keys não existe.");
      process.exit(1);
    }
    rows.forEach((r: any) => console.log(r.COLUMN_NAME, r.COLUMN_TYPE, "DEFAULT", r.COLUMN_DEFAULT));
    console.log("\n--- Índices ---");
    (idx || []).forEach((r: any) => console.log(r.INDEX_NAME, "UNIQUE:", r.NON_UNIQUE === 0, "COL:", r.COLUMN_NAME));
    const uniqueCmdKey = (idx || []).find((r: any) => r.INDEX_NAME === "idempotency_cmd_key" && r.NON_UNIQUE === 0);
    if (!uniqueCmdKey) {
      console.error("\nFALHA: índice UNIQUE idempotency_cmd_key (commandName, key) não encontrado.");
      process.exit(1);
    }
    const createdAtIndex = (idx || []).find((r: any) => r.INDEX_NAME === "idempotency_created_at_idx" && r.COLUMN_NAME === "created_at");
    if (!createdAtIndex) {
      console.error("\nFALHA: índice idempotency_created_at_idx em created_at não encontrado.");
      process.exit(1);
    }
    const createdAtCol = (rows || []).find((r: any) => r.COLUMN_NAME === "created_at");
    if (!createdAtCol || (createdAtCol.COLUMN_DEFAULT !== "CURRENT_TIMESTAMP" && String(createdAtCol.COLUMN_DEFAULT || "").toLowerCase() !== "current_timestamp()")) {
      console.error("\nFALHA: coluna created_at sem DEFAULT CURRENT_TIMESTAMP (ou current_timestamp()).");
      process.exit(1);
    }
    console.log("\nOK: tabela idempotency_keys existe com UNIQUE(commandName, key), índice em created_at e created_at DEFAULT CURRENT_TIMESTAMP.");
    process.exit(0);
  } catch (e: any) {
    console.error("Erro:", e?.message || e);
    process.exit(1);
  }
}

main();

import { z } from "zod";
import { toolExecutor } from "../leo/agent/tool-executor.js";
import { toolRegistry } from "../leo/agent/tool-registry.js";
import type { SecureToolContext } from "../_core/secure-context.js";

const tenantContext: SecureToolContext = {
  tenantId: 1,
  userId: 1,
  role: "admin",
  userRole: "admin",
  vendedorId: 1,
  __fromTool: true as const,
};

let flakyAttempts = 0;

toolRegistry.register({
  name: "failsafe_flaky_tool",
  description: "Tool de teste para retry automático",
  inputSchema: z.object({}),
  handler: async () => {
    flakyAttempts += 1;
    if (flakyAttempts < 3) {
      throw new Error(`Falha simulada ${flakyAttempts}`);
    }
    return { ok: true, attempts: flakyAttempts };
  },
});

toolRegistry.register({
  name: "failsafe_timeout_tool",
  description: "Tool de teste para timeout",
  inputSchema: z.object({}),
  handler: async () =>
    new Promise((resolve) => {
      setTimeout(() => resolve({ ok: true }), 20000);
    }),
});

async function run(): Promise<void> {
  console.log("[FAILSAFE] Iniciando teste de retry...");
  const retryResult = await toolExecutor.executeTool("failsafe_flaky_tool", {}, tenantContext);
  console.log("[FAILSAFE] Retry result:", JSON.stringify(retryResult));

  console.log("[FAILSAFE] Iniciando teste de timeout...");
  const timeoutResult = await toolExecutor.executeTool("failsafe_timeout_tool", {}, tenantContext);
  console.log("[FAILSAFE] Timeout result:", JSON.stringify(timeoutResult));

  const retryOk = retryResult.success === true;
  const timeoutOk = timeoutResult.success === false && (timeoutResult.error ?? "").includes("Fallback");

  if (!retryOk || !timeoutOk) {
    throw new Error(
      `Validação fail-safe falhou. retryOk=${String(retryOk)} timeoutOk=${String(timeoutOk)}`
    );
  }

  console.log("[FAILSAFE] Validação concluída com sucesso.");
}

run().catch((error: unknown) => {
  const message = error instanceof Error ? error.message : String(error);
  console.error("[FAILSAFE] Erro:", message);
  process.exit(1);
});

/**
